from pathlib import Path
import re, base64
root=Path('.')
header=base64.b64decode('').decode()
(root/'components/oim_protocol/include/oim_protocol.hpp').write_text(header)
p=root/'components/oim_config/oim_config.cpp'
s=p.read_text()
s=s.replace('#include "lwip/inet.h"','#include "lwip/ip_addr.h"')
if '#include "lwip/ip_addr.h"' not in s:
    s=s.replace('#include "nvs.h"','#include "nvs.h"\n#include "lwip/ip_addr.h"')
block=base64.b64decode('').decode()
start=s.find('bool is_valid_ntp_server(')
end=s.find('bool is_valid_server_url(', start)
if start < 0 or end < 0: raise SystemExit('oim_config function boundary not found')
s=s[:start]+block+s[end:]
p.write_text(s)
# Sanity: malformed compact-patch artifact must be absent.
if "canonicalize_server_url',e_server_url" in s: raise SystemExit('malformed canonical wrapper remains')
print('v2.1.11 CI postfix applied')
